#![allow(clippy::possible_missing_else)]
#![allow(clippy::needless_return)]
use std::{collections::HashSet, env, fs, path::{Path, PathBuf}, process::ExitCode, sync::Arc};
use one_core::{analyze, lower, parse, Capability, CapabilitySet, ExecutionPolicy, FilesystemAuthority, Interpreter, ScopeRule};
const VERSION: &str = "0.1.0";
fn usage() { println!("One v{VERSION}\n\nPenggunaan:\n  one buat <folder>\n  one periksa <file.one>\n  one jalankan <file.one> [--izinkan network.discover --target <alamat>]\n  one jalankan <file.one> [--izinkan network.connect --target <url>]\n  one jalankan <file.one> [--izinkan filesystem.read --target <path>]\n  one jalankan <file.one> [--izinkan filesystem.write --target <path>]\n  one jalankan <file.one> [--izinkan process.execute --target <program>]\n  one jalankan <file.one> [--izinkan database.query --target <database>]\n  one test <folder>\n  one bangun <file.one>\n  one package <folder>\n  one lihat struktur <file.one>\n  one version\n  one help\n\nAlias teknis:\n  one new <folder>\n  one check <file.one>\n  one run <file.one> [--allow network.discover --target <alamat>]\n  one build <file.one>\n  one ast <file.one>\n\nOrchestration:\n  --izinkan <capability> --target <target>\n    memberi izin eksplisit dan hanya untuk target tersebut."); }
fn print_diagnostics(bundle: &one_core::DiagnosticBundle) { for diagnostic in &bundle.0 { eprintln!("{}: {}", diagnostic.code, diagnostic.message); if let Some(span) = &diagnostic.span { eprintln!("  baris {}, kolom {}", span.line, span.column); } for note in &diagnostic.notes { eprintln!("  catatan: {}", note); } for suggestion in &diagnostic.suggestions { eprintln!("  saran: {}", suggestion); } } }
fn compile_source(source: &str) -> Result<(one_core::Program, one_core::TypedProgram), one_core::DiagnosticBundle> { let program = parse(source)?; let typed = analyze(&program)?; Ok((program, typed)) }
fn project_main(root: &Path) -> Result<PathBuf, String> { let path = root.join("src").join("main.one"); if path.is_file() { Ok(path) } else { Err(format!("Proyek tidak memiliki '{}'.", path.display())) } }
fn valid_artifact_component(value: &str) -> bool { !value.is_empty() && value.trim() == value && value != "." && value != ".." && !value.ends_with('.') && !value.ends_with(' ') && value.chars().all(|ch| !ch.is_control() && !matches!(ch, '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|')) }
fn project_metadata(root: &Path) -> Result<(String, String), String> { let manifest = root.join("one.toml"); let text = fs::read_to_string(&manifest).map_err(|e| format!("Tidak dapat membaca '{}': {}", manifest.display(), e))?; let mut seen = HashSet::new(); let mut name = None; let mut version = None; for (index, raw_line) in text.lines().enumerate() { let line = raw_line.trim(); if line.is_empty() || line.starts_with('#') { continue; } let Some((raw_key, raw_value)) = line.split_once('=') else { return Err(format!("Manifest '{}' memiliki baris tidak valid {}.", manifest.display(), index + 1)); }; let key = raw_key.trim(); let value = raw_value.trim(); if !matches!(key, "nama" | "versi") || !seen.insert(key) { return Err(format!("Manifest '{}' memiliki field tidak valid atau duplikat pada baris {}.", manifest.display(), index + 1)); } let Some(value) = value.strip_prefix('"').and_then(|v| v.strip_suffix('"')) else { return Err(format!("Manifest '{}' memiliki nilai tidak valid pada baris {}.", manifest.display(), index + 1)); }; if value.is_empty() { return Err(format!("Manifest '{}' memiliki nilai kosong pada baris {}.", manifest.display(), index + 1)); } if !valid_artifact_component(value) { return Err(format!("Manifest '{}' memiliki nilai tidak aman untuk nama artefak pada baris {}.", manifest.display(), index + 1)); } match key { "nama" => name = Some(value.to_owned()), "versi" => version = Some(value.to_owned()), _ => unreachable!() } } match (name, version) { (Some(name), Some(version)) => Ok((name, version)), _ => Err(format!("Manifest '{}' harus memuat nama dan versi.", manifest.display())) } }
fn project_root_for_source(source: &Path) -> Result<PathBuf, String> {
 let current_dir = fs::canonicalize(".")
  .map_err(|error| format!("Tidak dapat menentukan direktori kerja proyek: {}", error))?;
 let source_parent = source.parent().unwrap_or_else(|| Path::new("."));
 let canonical_parent = fs::canonicalize(source_parent)
  .map_err(|error| format!("Tidak dapat menentukan direktori sumber '{}': {}", source_parent.display(), error))?;

 // Prefer the nearest ancestor containing the project manifest. This makes
 // the host choose the authority root from project/source context, never from
 // the requested filesystem target.
 let mut candidate = canonical_parent.clone();
 loop {
  if candidate.join("one.toml").is_file() {
   return Ok(candidate);
  }
  if candidate == current_dir {
   break;
  }
  let Some(parent) = candidate.parent() else {
   break;
  };
  if parent == candidate {
   break;
  }
  candidate = parent.to_path_buf();
 }

 // Standalone relative source files belong to the current working directory;
 // standalone absolute source files use their canonical containing directory.
 if source.is_absolute() {
  Ok(canonical_parent)
 } else {
  Ok(current_dir)
 }
}

fn filesystem_authority_for_target(source: &Path, target: &str) -> Result<(Arc<FilesystemAuthority>, String), String> {
 let root = project_root_for_source(source)?;
 let canonical_root = fs::canonicalize(&root)
  .map_err(|error| format!("Tidak dapat menentukan root proyek '{}': {}", root.display(), error))?;
 let authority = FilesystemAuthority::open(&canonical_root, 1_048_576, 1_048_576)
  .map_err(|error| format!("Tidak dapat membangun otoritas filesystem untuk target '{}': {:?}", target, error))?;
 // The host-selected project root is independent of the requested target.
 // The retained authority rejects absolute targets outside this root.
 Ok((Arc::new(authority), target.to_owned()))
}
fn compile_file(path: &Path) -> Result<(one_core::Program, one_core::TypedProgram), one_core::DiagnosticBundle> { let source = fs::read_to_string(path).map_err(|error| one_core::DiagnosticBundle::single(one_core::Diagnostic::error("ETOOL001", format!("Tidak dapat membaca '{}': {}", path.display(), error), None)))?; compile_source(&source) }
fn fixture_files(root: &Path) -> Result<Vec<PathBuf>, String> { if !root.is_dir() { return Ok(Vec::new()); } let mut files = fs::read_dir(root).map_err(|e| format!("Tidak dapat membaca '{}': {}", root.display(), e))?.map(|entry| entry.map(|e| e.path()).map_err(|e| format!("Tidak dapat membaca fixture: {}", e))).collect::<Result<Vec<_>, _>>()?; files.retain(|path| path.extension().and_then(|v| v.to_str()) == Some("one")); files.sort(); Ok(files) }
fn run_conformance_fixtures(root: &Path) -> Result<usize, String> { let valid = fixture_files(&root.join("tests/conformance/valid"))?; let invalid = fixture_files(&root.join("tests/conformance/invalid"))?; let mut count = 0; for path in valid { let (_, typed) = compile_file(&path).map_err(|bundle| format!("Fixture valid '{}' ditolak: {}", path.display(), bundle.0.first().map(|d| d.message.as_str()).unwrap_or("diagnostic tidak tersedia")))?; let ir = lower(&typed).map_err(|bundle| format!("Fixture valid '{}' gagal diturunkan: {}", path.display(), bundle.0.first().map(|d| d.message.as_str()).unwrap_or("diagnostic tidak tersedia")))?; let mut interpreter = Interpreter::new(CapabilitySet::none()); interpreter.execute(&ir).map_err(|error| format!("Fixture valid '{}' gagal saat runtime: {}", path.display(), error.message))?; count += 1; } for path in invalid { let result = compile_file(&path); if result.is_ok() { return Err(format!("Fixture invalid '{}' diterima.", path.display())); } count += 1; } Ok(count) }
fn main() -> ExitCode {
 let mut args = env::args().skip(1); let Some(first) = args.next() else { usage(); return ExitCode::from(2); }; if first == "help" { if args.next().is_some() { usage(); return ExitCode::from(2); } usage(); return ExitCode::SUCCESS; } if first == "version" { if args.next().is_some() { usage(); return ExitCode::from(2); } println!("one {VERSION}"); return ExitCode::SUCCESS; }
 let command = match first.as_str() { "buat" | "new" => "new", "periksa" | "check" => "check", "jalankan" | "run" => "run", "bangun" | "build" => "build", "ast" => "ast", "test" => "test", "package" => "package", "lihat" if args.next().as_deref() == Some("struktur") => "ast", _ => { usage(); return ExitCode::from(2); } };
 if command == "new" { let Some(folder) = args.next() else { usage(); return ExitCode::from(2); }; if args.next().is_some() { usage(); return ExitCode::from(2); } let root = Path::new(&folder); if root.exists() { eprintln!("Folder '{}' sudah ada.", folder); return ExitCode::from(2); } let src = root.join("src"); if let Err(error) = fs::create_dir_all(&src).and_then(|_| fs::write(root.join("one.toml"), "nama = \"proyek-one\"\nversi = \"0.1.0\"\n")).and_then(|_| fs::write(src.join("main.one"), "tampilkan \"Halo dari One\"\n")) { eprintln!("Gagal membuat proyek: {}", error); return ExitCode::from(2); } println!("Proyek One dibuat di {}", root.display()); return ExitCode::SUCCESS; }
 let Some(path_arg) = args.next() else { usage(); return ExitCode::from(2); }; let path = Path::new(&path_arg); let mut orchestration_target = None; let mut orchestration_capability = None;
 if command == "run" { while let Some(option) = args.next() { match option.as_str() { "--izinkan" | "--allow" => { let Some(capability) = args.next() else { eprintln!("ETOOL004: --izinkan membutuhkan capability."); return ExitCode::from(2); }; if !matches!(capability.as_str(), "network.discover" | "network.connect" | "filesystem.read" | "filesystem.write" | "process.execute" | "database.query") { eprintln!("ETOOL004: capability '{}' belum tersedia melalui CLI.", capability); return ExitCode::from(2); } orchestration_capability = Some(capability); }, "--target" => { let Some(target) = args.next() else { eprintln!("ETOOL004: --target membutuhkan target."); return ExitCode::from(2); }; orchestration_target = Some(target); }, _ => { usage(); return ExitCode::from(2); } } } } else if args.next().is_some() { usage(); return ExitCode::from(2); }
 if orchestration_target.is_some() != orchestration_capability.is_some() { eprintln!("ETOOL004: --izinkan dan --target harus diberikan bersama."); return ExitCode::from(2); }
 if command == "test" || command == "package" { let root = if path.is_dir() { path.to_path_buf() } else { path.parent().unwrap_or_else(|| Path::new(".")).to_path_buf() }; let (name, version) = match project_metadata(&root) { Ok(value) => value, Err(message) => { eprintln!("ETOOL002: {message}"); return ExitCode::from(2); } }; let main_file = match project_main(&root) { Ok(value) => value, Err(message) => { eprintln!("ETOOL001: {message}"); return ExitCode::from(2); } }; let (_, typed) = match compile_file(&main_file) { Ok(value) => value, Err(error) => { print_diagnostics(&error); return ExitCode::from(1); } }; let ir = match lower(&typed) { Ok(value) => value, Err(error) => { print_diagnostics(&error); return ExitCode::from(1); } }; if command == "test" { let mut interpreter = Interpreter::new(CapabilitySet::none()); match interpreter.execute(&ir) { Ok(_) => match run_conformance_fixtures(&root) { Ok(count) => { println!("Tests berhasil: {} ({} fixture)", root.display(), count + 1); ExitCode::SUCCESS }, Err(message) => { eprintln!("ETOOL003: {message}"); ExitCode::from(1) } }, Err(error) => { eprintln!("{}: {}", error.code, error.message); ExitCode::from(1) } } } else { let target = root.join("target"); if let Err(error) = fs::create_dir_all(&target) { eprintln!("Gagal membuat target: {}", error); return ExitCode::from(2); } let artifact = target.join(format!("{name}-{version}.onepkg")); let manifest = match fs::read_to_string(root.join("one.toml")) { Ok(value) => value, Err(error) => { eprintln!("ETOOL002: Tidak dapat membaca manifest: {error}"); return ExitCode::from(2); } }; let contents = format!("One package v0.1\n\n[manifest]\n{manifest}\n[ir]\n{}", ir.canonical_text()); if let Err(error) = fs::write(&artifact, contents) { eprintln!("Gagal menulis paket: {}", error); return ExitCode::from(2); } println!("Paket berhasil: {}", artifact.display()); ExitCode::SUCCESS } } else { let (program, typed) = match compile_file(path) { Ok(value) => value, Err(error) => { print_diagnostics(&error); return ExitCode::from(1); } }; match command { "check" => { println!("OK: {}", path.display()); ExitCode::SUCCESS }, "ast" => { println!("{:#?}", program); ExitCode::SUCCESS }, "run" => match lower(&typed) { Ok(ir) => { let mut interpreter = match (orchestration_capability, orchestration_target) { (Some(capability), Some(target)) => match capability.as_str() { "network.discover" => Interpreter::with_orchestration_policy(ExecutionPolicy::default().grant(Capability::NetworkDiscover).allow_scope(Capability::NetworkDiscover, ScopeRule::Target(target))), "network.connect" => Interpreter::with_orchestration_policy(ExecutionPolicy::default().grant(Capability::NetworkConnect).allow_scope(Capability::NetworkConnect, ScopeRule::Target(target))), "filesystem.read" => { let (authority, scoped_target) = match filesystem_authority_for_target(path, &target) { Ok(value) => value, Err(message) => { eprintln!("ETOOL005: {message}"); return ExitCode::from(2); } }; Interpreter::with_orchestration_policy_and_filesystem_authority(ExecutionPolicy::default().grant(Capability::FilesystemRead).allow_scope(Capability::FilesystemRead, ScopeRule::Target(scoped_target)), authority) }, "filesystem.write" => { let (authority, scoped_target) = match filesystem_authority_for_target(path, &target) { Ok(value) => value, Err(message) => { eprintln!("ETOOL005: {message}"); return ExitCode::from(2); } }; Interpreter::with_orchestration_policy_and_filesystem_authority(ExecutionPolicy::default().grant(Capability::FilesystemWrite).allow_scope(Capability::FilesystemWrite, ScopeRule::Target(scoped_target)), authority) }, "process.execute" => Interpreter::with_orchestration_policy(ExecutionPolicy::default().grant(Capability::Process).allow_scope(Capability::Process, ScopeRule::Target(target))), "database.query" => Interpreter::with_orchestration_policy(ExecutionPolicy::default().grant(Capability::DatabaseQuery).allow_scope(Capability::DatabaseQuery, ScopeRule::Resource(target))), _ => unreachable!() }, (None, None) => Interpreter::new(CapabilitySet::none()), _ => unreachable!() }; match interpreter.execute(&ir) { Ok(result) => { for line in result.output { println!("{}", line); } ExitCode::SUCCESS }, Err(error) => { eprintln!("{}: {}", error.code, error.message); ExitCode::from(1) } } }, Err(error) => { print_diagnostics(&error); return ExitCode::from(1) } }, "build" => match lower(&typed) { Ok(ir) => { let parent = path.parent().unwrap_or_else(|| Path::new(".")).to_path_buf(); let target = parent.join("target"); if let Err(error) = fs::create_dir_all(&target) { eprintln!("Gagal menulis artefak build: {}", error); return ExitCode::from(2) } let output = target.join(format!("{}.oneir", path.file_stem().and_then(|v| v.to_str()).unwrap_or("program"))); if let Err(error) = fs::write(&output, ir.canonical_text()) { eprintln!("Gagal menulis artefak build: {}", error); return ExitCode::from(2) } println!("Build berhasil: {}", output.display()); ExitCode::SUCCESS }, Err(error) => { print_diagnostics(&error); return ExitCode::from(1) } }, _ => { usage(); return ExitCode::from(2) } } }
}